const needRoot=(c,msg)=>{if(!isRoot()){c.el(msg);return true;}return false;};
const upMin=()=>W.t-W.boot;
function upStr(){const m=upMin();const d=Math.floor(m/1440),h=Math.floor(m%1440/60),mm=m%60;return `${d>0?d+' day'+(d>1?'s':'')+', ':''}${h}:${p2(mm)}`;}
const clock=()=>{const d=dt(W.t,W.seq%60);return `${p2(d.getUTCHours())}:${p2(d.getUTCMinutes())}:${p2(d.getUTCSeconds())}`;};
const f1=x=>x.toFixed(1);
const commOf=p=>{const w=p.cmd.replace(/^\[|\]$/g,'').split(' ')[0];if(/^nginx:/.test(p.cmd))return 'nginx';if(/^sshd:/.test(p.cmd))return 'sshd';if(/^postgres/.test(p.cmd))return 'postgres';const b=basename(w);return b.replace(/^-/,'');};
function userLine(u){const g=getGroups();const us=getUsers().find(x=>x.n===u);if(!us)return null;const pg=g.find(x=>x.gid===us.gid);const sup=g.filter(x=>x.mem.includes(u)&&x.gid!==us.gid);return{us,pg,sup};}

