CMD.vmstat=(c,a)=>{const{pos}=po(a);const n=+pos[1]||5;const mi=memInfo();const cpu=Math.min(100,W.procs.reduce((x,p)=>x+p.cpu,0));c.pl('procs -----------memory---------- ---swap-- -----io---- -system-- ------cpu-----');c.pl(' r  b   swpd   free   buff  cache   si   so    bi    bo   in   cs us sy id wa st');
 for(let i=0;i<Math.min(n,6);i++){const us=Math.round(cpu*.8),sy=Math.round(cpu*.2);c.pl(`${String(W.procs.filter(p=>p.st==='R').length+(i%2)).padStart(2)}  0 ${String(Math.round(mi.swapU)).padStart(6)} ${String(Math.round(mi.free)).padStart(6)} ${String(Math.round(mi.cache*.1)).padStart(6)} ${String(Math.round(mi.cache*.9)).padStart(6)}    0    0    ${W.ioWait?'4120':'12'}    ${W.ioWait?'9800':'30'}  ${180+i*7} ${320+i*11} ${String(us).padStart(2)} ${String(sy).padStart(2)} ${String(Math.max(0,100-us-sy-(W.ioWait?40:0))).padStart(2)} ${String(W.ioWait?40:0).padStart(2)}  0`);}return 0;};
