 if(hasF(f,'-x')){c.pl('Device            r/s     rkB/s   rrqm/s  %rrqm r_await rareq-sz     w/s     wkB/s  w_await  %util');['sda','sdb'].forEach((d,i)=>c.pl(`${d.padEnd(10)}${(W.ioWait&&i===0?'420.00':'1.20').padStart(10)}${(W.ioWait&&i===0?'53000.0':'14.2').padStart(10)}      0.00   0.00    ${W.ioWait&&i===0?'18.4':'0.40'}    ${'32.0'}    ${W.ioWait&&i===0?'210.0':'0.90'}${'3400.0'.padStart(10)}    ${W.ioWait&&i===0?'22.1':'0.60'}${(W.ioWait&&i===0?'98.7':'0.3').padStart(8)}`));}
