CMD.renice=(c,a)=>{const{pos,f}=po(a,['-n','-p','-u']);const nv=valF(f,'-n')??pos[0];const pids=(valF(f,'-p')?[valF(f,'-p'),...pos.slice(valF(f,'-n')?0:1)]:pos.slice(1)).map(Number).filter(Boolean);let st=0;if(nv===undefined||!pids.length){c.el('renice: missing priority/pid');return 1;}
 pids.forEach(pid=>{const p=procBy(pid);if(!p){c.el(`renice: failed to get priority for ${pid} (process ID): No such process`);st=1;return;}if(!isRoot()&&(p.user!==W.user||+nv<p.nice)){c.el(`renice: failed to set priority for ${pid} (process ID): ${+nv<p.nice?'Permission denied':'Operation not permitted'}`);st=1;return;}
  const old=p.nice;p.nice=+nv;if(p.cpu>5)p.cpu=Math.max(2,p.cpu*Math.pow(0.82,(+nv-old)));c.pl(`${pid} (process ID) old priority ${old}, new priority ${nv}`);});return st;};

