 const gs=[pg,...sup].filter(Boolean);if(hasF(f,'-u')){c.pl(hasF(f,'-n')?u:String(us.uid));return 0;}if(hasF(f,'-g')){c.pl(hasF(f,'-n')?pg.n:String(us.gid));return 0;}if(hasF(f,'-G')){c.pl(gs.map(g=>hasF(f,'-n')?g.n:g.gid).join(' '));return 0;}
