/* ---- cron ---- */
function cronLineErr(l){const t=l.trim();if(!t||t[0]==='#')return null;if(/^[A-Za-z_]\w*\s*=/.test(t))return null;let parts=t.split(/\s+/);if(parts[0][0]==='@'){return ['@reboot','@hourly','@daily','@weekly','@monthly','@yearly','@annually','@midnight'].includes(parts[0])&&parts.length>=2?null:'bad command';}
 if(parts.length<6)return 'bad command';const rng=[[0,59,'minute'],[0,23,'hour'],[1,31,'day-of-month'],[1,12,'month'],[0,7,'day-of-week']];
 for(let i=0;i<5;i++){const fld=parts[i];const ok=fld.split(',').every(p=>{const m=p.match(/^(\*|(\d+|[A-Za-z]{3})(-(\d+|[A-Za-z]{3}))?)(\/(\d+))?$/);if(!m)return false;if(m[2]&&/^\d+$/.test(m[2])&&(+m[2]<rng[i][0]||+m[2]>rng[i][1]))return false;if(m[4]&&/^\d+$/.test(m[4])&&+m[4]>rng[i][1])return false;return true;});if(!ok)return 'bad '+rng[i][2];}return null;}
function fieldMatch(f,v,lo,hi){return f.split(',').some(p=>{let[r,step]=p.split('/');step=step?+step:1;let a,b;if(r==='*'){a=lo;b=hi;}else if(r.includes('-')){[a,b]=r.split('-').map(Number);}else{a=+r;b=step>1?hi:+r;}return v>=a&&v<=b&&(v-a)%step===0;});}
